CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('admin')), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY read_own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.is_feedback_admin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin') $$;
REVOKE ALL ON FUNCTION public.is_feedback_admin() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.is_feedback_admin() TO authenticated, service_role;
CREATE TABLE public.outfit_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), title text NOT NULL CHECK (char_length(title) BETWEEN 1 AND 120), feedback text NOT NULL CHECK (char_length(feedback) BETWEEN 1 AND 6000), context text NOT NULL DEFAULT '' CHECK (char_length(context) <= 4000), situation text NOT NULL CHECK (situation IN ('home','walk','car')), status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','resolved')));
GRANT SELECT, INSERT, UPDATE, DELETE ON public.outfit_reports TO authenticated;
GRANT ALL ON public.outfit_reports TO service_role;
ALTER TABLE public.outfit_reports ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_reports ON public.outfit_reports FOR ALL TO authenticated USING (public.is_feedback_admin()) WITH CHECK (public.is_feedback_admin());
CREATE TABLE public.outfit_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), report_ids uuid[] NOT NULL, result jsonb NOT NULL, model text NOT NULL);
GRANT SELECT, INSERT ON public.outfit_analyses TO authenticated;
GRANT ALL ON public.outfit_analyses TO service_role;
ALTER TABLE public.outfit_analyses ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_analysis_read ON public.outfit_analyses FOR SELECT TO authenticated USING (public.is_feedback_admin());
CREATE POLICY admin_analysis_insert ON public.outfit_analyses FOR INSERT TO authenticated WITH CHECK (public.is_feedback_admin() AND created_by = auth.uid());
CREATE TABLE public.outfit_ai_state (id boolean PRIMARY KEY DEFAULT true CHECK (id), blocked_message text NOT NULL, blocked_type text NOT NULL, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.outfit_ai_state TO authenticated;
GRANT ALL ON public.outfit_ai_state TO service_role;
ALTER TABLE public.outfit_ai_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY admin_ai_state ON public.outfit_ai_state FOR ALL TO authenticated USING (public.is_feedback_admin()) WITH CHECK (public.is_feedback_admin());
CREATE INDEX outfit_reports_created_at ON public.outfit_reports(created_at DESC);